#!/usr/bin/env node

const fs = require('fs');

const ELF_CLASS_32 = 1;
const ELF_CLASS_64 = 2;
const ELF_DATA_2_LSB = 1;

function readElfHeader(buf) {
  if (buf.length < 16 || buf.readUInt32BE(0) !== 0x7f454c46) {
    throw new Error('Not a valid ELF file');
  }

  const elfClass = buf[4];
  const elfData = buf[5];
  const le = elfData === ELF_DATA_2_LSB;

  const u16 = (off) => (le ? buf.readUInt16LE(off) : buf.readUInt16BE(off));
  const u32 = (off) => (le ? buf.readUInt32LE(off) : buf.readUInt32BE(off));
  const u64 = (off) =>
    Number(le ? buf.readBigUInt64LE(off) : buf.readBigUInt64BE(off));
  const word = elfClass === ELF_CLASS_64 ? u64 : u32;

  return {
    elfClass,
    le,
    shoff: word(elfClass === ELF_CLASS_64 ? 40 : 32),
    shentsize: u16(elfClass === ELF_CLASS_64 ? 58 : 46),
    shnum: u16(elfClass === ELF_CLASS_64 ? 60 : 48),
    shstrndx: u16(elfClass === ELF_CLASS_64 ? 62 : 50),
  };
}

function readSectionHeaders(buf, header) {
  const { elfClass, le, shoff, shentsize, shnum } = header;
  const u32 = (off) => (le ? buf.readUInt32LE(off) : buf.readUInt32BE(off));
  const u64 = (off) =>
    Number(le ? buf.readBigUInt64LE(off) : buf.readBigUInt64BE(off));
  const word = elfClass === ELF_CLASS_64 ? u64 : u32;

  const sections = [];
  for (let i = 0; i < shnum; i++) {
    const base = shoff + i * shentsize;
    if (elfClass === ELF_CLASS_64) {
      sections.push({
        name: u32(base),
        addr: word(base + 16),
        offset: word(base + 24),
        size: word(base + 32),
      });
    } else {
      sections.push({
        name: u32(base),
        addr: word(base + 12),
        offset: word(base + 16),
        size: word(base + 20),
      });
    }
  }
  return sections;
}

function getString(buffer, offset) {
  if (offset >= buffer.length) return '';
  let end = offset;
  while (end < buffer.length && buffer[end] !== 0) end++;
  return buffer.slice(offset, end).toString();
}

function extract(elfPath) {
  const buf = fs.readFileSync(elfPath);
  const header = readElfHeader(buf);
  const sections = readSectionHeaders(buf, header);

  const shstrtab = sections[header.shstrndx];
  const shstr = buf.slice(shstrtab.offset, shstrtab.offset + shstrtab.size);

  const wanted = new Set(['.text', '.data', '.rodata']);
  const memory = {};

  for (const section of sections) {
    if (!wanted.has(getString(shstr, section.name))) continue;

    const data = buf.slice(section.offset, section.offset + section.size);
    for (let i = 0; i + 4 <= data.length; i += 4) {
      memory[section.addr + i] = data.readUInt32LE(i);
    }
  }

  return memory;
}

if (require.main === module) {
  if (process.argv.length < 3) {
    console.error('Usage: node extract.js <elf_file>');
    process.exit(1);
  }
  console.log(JSON.stringify(extract(process.argv[2])));
}

